lgt <- function(yn, p) {
  u <- par("usr")
  cx <- par("cex")
  sx <- diff(u[1:2]) / par("pin")[1]
  sy <- diff(u[3:4]) / par("pin")[2]
  f <- quote(frac(p, 1 - p))
  wl <- strwidth("log", "inches", cx)
  wf <- strwidth(f, "inches", cx)
  h <- 1.1 * strheight(f, "inches", cx)
  xh <- strheight("x", "inches", cx)
  g <- 0.3 * xh
  wp <- 0.22 * h
  d <- 0.6 * wp
  a <- -(wl + 2 * g + 2 * wp + wf) / 2
  xc <- u[1] - (yn * par("mai")[2] / par("mar")[2] + h / 2) * sx
  yc <- mean(u[3:4])
  q <- function(s, v) cbind(xc - v * sx, yc + s * sy)
  v <- seq(-h / 2, h / 2, length.out = 50)
  e <- d * (2 * v / h)^2
  text(q(a, -xh / 2), labels = "log", srt = 90, adj = c(0, 0), cex = cx, col = p[["lab"]], xpd = NA)
  b <- a + wl + g
  lines(q(b + (wp - d) / 2 + e, v), col = p[["lab"]], lwd = cx, xpd = NA)
  text(q(b + wp + g + wf / 2, 0), labels = as.expression(f), srt = 90, cex = cx, col = p[["lab"]], xpd = NA)
  b <- b + wp + 2 * g + wf
  lines(q(b + (wp + d) / 2 - e, v), col = p[["lab"]], lwd = cx, xpd = NA)
}

fr <- function(yl, tt, p, yn = 3) {
  u <- par("usr")
  par(family = if (is.character(yl)) "sans" else "serif")
  if (is.function(yl)) yl(yn, p) else mtext(yl, 2, yn, col = p[["lab"]], cex = par("cex"), xpd = NA)
  par(family = "serif")
  mtext(expression(bold(x)), 1, 3, col = p[["lab"]], cex = par("cex"))
  par(family = "sans")
  mtext(tt, 3, 1, font = 2, cex = par("cex"))
  rect(u[1], u[3], u[2], u[4], col = p[["panel"]], border = NA)
  g <- function(t) seq(t[1] - diff(t[1:2]), t[length(t)] + diff(t[1:2]), diff(t[1:2]) / 2)
  abline(h = g(axTicks(2)), v = g(axTicks(1)), lwd = 2, col = p[["bg"]])
  abline(h = axTicks(2), v = axTicks(1), lwd = 3, col = p[["bg"]])
  eaxis(1, col = p[["ax"]], col.axis = p[["ax"]], col.ticks = p[["ax"]], small.args = list(col = p[["ax"]]))
  eaxis(2, col = p[["ax"]], col.axis = p[["ax"]], col.ticks = p[["ax"]], small.args = list(col = p[["ax"]]))
}

dat <- function(e, v, p, bd = "none") {
  d <- e$d
  po <- e$fam == "poisson"
  m <- fit(d, e$fam)
  tr <- function(x) mu(x, e$fam, e$type, e$lvl, e$sg)
  lk <- if (po) log else qlogis
  r <- range(d$x)
  g <- seq(r[1] - 0.04 * diff(r), r[2] + 0.04 * diff(r), length.out = 200)
  y <- d$y
  k <- if (po) 1 else 10
  j <- seq_len(min(3, nrow(d)))
  i <- unique(c(order(-e$cd)[j], which(e$r$u %in% c(0, 1))))
  par(mfrow = if (v) c(2, 1) else c(1, 2), mar = c(5, 5, 3, 3) + 0.1)
  par(cex = 0.83)
  a <- predict(m, data.frame(x = g), type = "response")
  plot(d$x, y, type = "n", bty = "n", axes = FALSE, xlab = "", ylab = "", ylim = c(0, if (po) max(10, y, a, tr(g)) else 10))
  fr(if (po) "Count" else "Successes (out of 10)", "Scale of the outcome", p)
  if (!is.null(bd) && bd != "none") {
    q <- if (bd == "true") tq(g, e$fam, e$type, e$lvl, e$sg) else
      sapply(c(0.025, 0.975), function(p) if (po) qpois(p, a) else qbinom(p, 10, a))
    q <- sweep(q, 2, c(-0.5, 0.5), "+")
    z <- c(g[1], rep(g[-1], each = 2))
    h <- function(y) rep(y, each = 2)[-2 * length(y)]
    polygon(c(z, rev(z)), c(h(q[, 1]), rev(h(q[, 2]))), border = NA,
            col = if (bd == "fit") adjustcolor(p[["line"]], 0.25) else adjustcolor(p[["tband"]], 0.22))
  }
  lines(g, k * tr(g), col = p[["true"]], lwd = 3)
  lines(g, k * a, col = p[["line"]], lwd = 3)
  legend("topleft", c("Fitted model", "True relationship"), col = p[c("line", "true")], lwd = 3, bty = "n")
  points(d$x, y, pch = 19)
  text(d$x[i], y[i], rownames(d)[i], pos = ifelse(d$x[i] > 0, 2, 4), cex = 0.8)
  b <- predict(m, data.frame(x = g))
  plot(r, range(b, lk(tr(g))), type = "n", bty = "n", axes = FALSE, xlab = "", ylab = "")
  fr(if (po) expression(log(lambda)) else lgt,
     expression(bold("Scale of the model (" * eta * ")")), p, if (po) 3 else 2.6)
  lines(g, lk(tr(g)), col = p[["true"]], lwd = 3)
  lines(g, b, col = p[["line"]], lwd = 3)
}

ckd <- function(D, p) {
  i <- seq_along(D)
  j <- order(-D)[seq_len(min(3, length(D)))]
  plot(i, D, type = "h", axes = FALSE, lwd = 2, lend = 1, las = 1, bty = "n", ylim = c(0, 1.08 * max(D, na.rm = TRUE)),
       xlab = "Observation number", ylab = "")
  mtext("Cook's distance", 2, 3, cex = par("cex"))
  mtext("Cook's distance", 3, 1.25, font = 2, cex = par("cex"))
  axis(1, cex.axis = 0.8)
  eaxis(2, cex.axis = 0.8)
  abline(h = 1, col = p[["red"]], lty = 3)
  abline(h = 0.5, col = p[["orange"]], lty = 3)
  text(j, D[j], j, pos = 3, cex = 0.8, xpd = TRUE)
}

zpl <- function(z, o, p, v = FALSE) {
  hist(z, xlim = range(z, o), col = p[["hist"]], breaks = 50, axes = FALSE, main = "", xlab = "")
  k <- axTicks(1)
  axis(1, k[k == round(k)], cex.axis = 0.8)
  eaxis(2, cex.axis = 0.8)
  a <- "Expected zeros with simulation"
  b <- quote(bold("under" ~ H[0] == "fitted model"))
  t <- bquote(bold(.(a) ~ .(b)))
  if (strwidth(t, "figure") < 0.95) {
    mtext(t, 3, 1.25, cex = par("cex"))
  } else {
    mtext(a, 3, 1.25, font = 2, cex = par("cex"))
    mtext(b, 3, 0.25, cex = par("cex"))
  }
  title(xlab = paste0("Simulated values, red line = fitted model.", if (v) "\n" else " ", "p-value (two.sided) = ", gp(z, o)),
        line = if (v) 3.2 else 2)
  abline(v = o, lwd = 2, col = p[["red"]])
}

lp <- 0.83 * 0.2 * 96

ar <- c(1.6, 1.9)

zw <- local({
  svg(tempfile())
  par(cex = 0.83)
  x <- strwidth("Simulated values, red line = fitted model. p-value (two.sided) = 0.000", "inches") * 96
  dev.off()
  x
})

mb <- function(v, z) 3.2 + z * c(0, 0, 1, !v)

sz <- function(wd, vh) {
  v <- wd < 600
  for (z in c(FALSE, TRUE)) {
    p <- if (v) wd else wd / 2
    d <- (p - 6.2 * lp) / ar[1]
    if (!v) {
      d <- max(min(d, (vh - 10) / 2 - (6.4 + z / 2) * lp), (300 - 6.2 * lp) / ar[2])
      p <- min(p, ar[2] * d + 6.2 * lp)
    }
    if (z || zw + 40 < p) break
  }
  hs <- d + ((if (v) mb(v, z) else mb(v, z)[c(1, 3)]) + 3.2) * lp
  list(v = v, z = z, w = round(if (v) p else 2 * p), h = round(sum(hs)), hs = hs)
}

dg <- function(e, s, p) {
  b <- mb(s$v, s$z)
  layout(if (s$v) matrix(1:4) else matrix(1:4, 2, byrow = TRUE), heights = s$hs)
  par(mar = c(b[1], 4, 3, 2) + 0.1, mgp = c(2, 0.75, 0))
  par(cex = 0.83)
  qqp(e$r, p)
  rvp(e$r, p)
  par(mar = c(b[3], 4, 3, 2) + 0.1)
  zpl(e$zs, e$zo, p, s$z)
  par(mar = c(b[4], 4, 3, 2) + 0.1)
  ckd(e$cd, p)
}

